import React, { useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, Bot, BrainCircuit,
  Building2, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft,
  ChevronRight, CircleHelp, Clock3, Command, CreditCard, Download, Ellipsis,
  ExternalLink, Eye, FileBarChart, Filter, Gauge, GitBranch, Globe2, LayoutDashboard,
  LifeBuoy, LockKeyhole, LogOut, Menu, MessageSquare, Moon, MoreHorizontal,
  PanelLeftClose, Plus, Search, Send, Settings, ShieldCheck, Sparkles, Sun,
  Target, Users, Workflow, Zap, Plug, Play, Pause, RefreshCw, X, Mail, KeyRound,
  Database, Webhook, ShoppingCart, CalendarCheck, Cloud, ChevronUp, Copy,
  CircleCheck, CircleAlert, Trash2, Edit3, SlidersHorizontal
} from "lucide-react";
import {
  Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart,
  ResponsiveContainer, Tooltip, XAxis, YAxis
} from "recharts";
import "./styles.css";
import { authenticate, apiRequest, restoreSession } from "./api.js";

