function AuthScreen({auth,setAuth,onDone}) {
  const [name,setName]=useState("");const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);
  const submit=async()=>{setError("");setBusy(true);try{await onDone(auth==="signup"?{name,email,password}:{email,password});}catch(e){setError(e.message||"Não foi possível autenticar.");}finally{setBusy(false);}};
  return <div className="auth-shell"><div className="auth-left"><Logo/><div className="auth-promo"><div className="eyebrow">O FUTURO DA OPERAÇÃO EMPRESARIAL</div><h1>O teu negócio.<br/><span>Em movimento.</span></h1><p>Transforma objetivos em operações autónomas. A inteligência artificial trata do trabalho, tu concentras-te no crescimento.</p><div className="auth-proof"><div className="proof-avatars"><i>FB</i><i>MC</i><i>JP</i><i>+</i></div><span>Construído para equipas que pensam em grande.</span></div></div><div className="auth-decoration"><div className="decor-orbit orbit1"/><div className="decor-orbit orbit2"/><div className="decor-core"><BrainCircuit size={40}/></div></div><small>© 2026 ZYVORA Technologies</small></div><div className="auth-right"><div className="auth-form-wrap"><div className="mobile-logo"><Logo/></div><div className="eyebrow">{auth==="login"?"BEM-VINDO DE VOLTA":"COMEÇA AQUI"}</div><h2>{auth==="login"?"Entra na tua conta":"Cria a tua conta"}</h2><p>{auth==="login"?"Continua a construir operações mais inteligentes.":"Começa a transformar a forma como o teu negócio trabalha."}</p><button className="social-login" onClick={()=>setError("O acesso Google será disponibilizado quando o OAuth estiver configurado no backend.")}><Globe2 size={17}/> Continuar com Google</button><div className="or-divider"><span/>ou com email<span/></div>{auth==="signup"&&<label className="field-label">Nome completo<input type="text" placeholder="O teu nome" value={name} onChange={e=>setName(e.target.value)}/></label>}<label className="field-label">Email profissional<input type="email" placeholder="nome@empresa.com" value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="field-label">Palavra-passe<input type="password" placeholder="Mínimo de 8 caracteres" value={password} onChange={e=>setPassword(e.target.value)}/></label>{auth==="signup"&&<label className="auth-check"><input type="checkbox" defaultChecked/> Aceito os <a>Termos de serviço</a> e a <a>Política de privacidade</a>.</label>}{error&&<div className="auth-error">{error}</div>}<Button block onClick={submit} disabled={busy}>{busy?"A processar...":auth==="login"?"Entrar na conta":"Criar conta gratuita"} <ArrowRight size={16}/></Button><div className="auth-switch">{auth==="login"?"Ainda não tens conta?":"Já tens uma conta?"} <button onClick={()=>setAuth(auth==="login"?"signup":"login")}>{auth==="login"?"Criar conta":"Iniciar sessão"}</button></div><div className="auth-secure"><ShieldCheck size={14}/> Ligação segura e dados encriptados</div></div></div></div>;
}

function Onboarding({company,setCompany,done}) {
  const [step,setStep]=useState(1);const [industry,setIndustry]=useState("Tecnologia");const [goal,setGoal]=useState("Aumentar vendas");const [size,setSize]=useState("2–10 pessoas");
  return <div className="onboarding-shell"><div className="onboarding-top"><Logo/><span>Configuração inicial <b>{step}/3</b></span></div><div className="onboarding-progress"><i style={{width:(step/3*100)+"%"}}/></div><div className="onboarding-card"><div className="onboarding-symbol"><Sparkles size={22}/></div><div className="eyebrow">VAMOS CONFIGURAR O TEU WORKSPACE</div><h1>{["","Vamos conhecer o teu negócio.","Quais são os teus objetivos?","Está tudo pronto."][step]}</h1><p>{["","Estas informações ajudam a ZYVORA a adaptar os agentes e as automações à tua realidade.","Escolhe a prioridade que terá maior impacto no teu negócio.","A tua área de trabalho está preparada para começar."][step]}</p>{step===1&&<><label className="field-label">Nome da empresa<input value={company} onChange={e=>setCompany(e.target.value)} /></label><label className="field-label">Setor de atividade<select value={industry} onChange={e=>setIndustry(e.target.value)}>{["Tecnologia","Comércio e retalho","Serviços profissionais","Educação","Saúde","Financeiro","Outro"].map(x=><option>{x}</option>)}</select></label><label className="field-label">Dimensão da equipa<select value={size} onChange={e=>setSize(e.target.value)}>{["Apenas eu","2–10 pessoas","11–50 pessoas","51–200 pessoas","Mais de 200 pessoas"].map(x=><option>{x}</option>)}</select></label></>}{step===2&&<div className="goal-options">{["Aumentar vendas","Automatizar operações","Melhorar suporte ao cliente","Reduzir custos","Obter melhores dados"].map(x=><button className={goal===x?"selected":""} onClick={()=>setGoal(x)} key={x}><span>{goal===x?<CheckCircle2 size={18}/>:<CircleCheck size={18}/>}</span>{x}</button>)}</div>}{step===3&&<div className="onboarding-complete"><CheckCircle2 size={36}/><b>{company}</b><span>{industry} · {size} · {goal}</span><Pill tone="success" dot>Workspace configurado</Pill></div>}<div className="onboarding-actions">{step>1&&<Button variant="secondary" onClick={()=>setStep(step-1)}>Voltar</Button>}<Button onClick={()=>step<3?setStep(step+1):done({industry,teamSize:size,primaryGoal:goal})}>{step===3?"Entrar no workspace":"Continuar"} <ArrowRight size={16}/></Button></div></div><div className="onboarding-help">Precisas de ajuda? <a>Fala com a nossa equipa</a></div></div>;
}

function Modal({type,close,notify,addWorkflow,addAgent}) {
  const [name,setName]=useState(type==="workflow"?"Nova automação":"Novo agente");const [description,setDescription]=useState("");
  const isWorkflow=type==="workflow";
  return <div className="modal-backdrop" onClick={close}><div className="modal-card" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">{type==="workspace"?"WORKSPACE":"CONFIGURAÇÃO AI"}</div><h2>{type==="workspace"?"Mudar workspace":isWorkflow?"Criar workflow com IA":"Criar agente AI"}</h2></div><button className="icon-btn" onClick={close}><X size={18}/></button></div>{type==="workspace"?<div className="workspace-option"><span className="workspace-avatar">A</span><div><b>Acme Studio</b><small>Workspace atual</small></div><CheckCircle2 size={17}/></div>:<><p className="modal-desc">{isWorkflow?"Descreve o resultado pretendido. A ZYVORA irá estruturar o processo para revisão.":"Define a especialidade e missão do novo agente."}</p><label className="field-label">{isWorkflow?"Nome do workflow":"Nome do agente"}<input value={name} onChange={e=>setName(e.target.value)}/></label><label className="field-label">{isWorkflow?"O que deve acontecer?":"Missão do agente"}<textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder={isWorkflow?"Ex.: Quando chega um novo lead, qualificar e agendar uma reunião...":"Ex.: Responder a clientes, identificar necessidades e encaminhar casos..."}/></label><div className="modal-note"><Sparkles size={15}/> A IA irá gerar uma proposta. Nenhuma ação externa será executada sem aprovação.</div></>}<div className="modal-actions"><Button variant="secondary" onClick={close}>Cancelar</Button><Button onClick={()=>{if(isWorkflow)addWorkflow({name,category:"Personalizado",status:"Rascunho",runs:"0",success:"—",updated:"Agora",color:"blue"});if(type==="agent")addAgent({name,role:"Agente personalizado",desc:description||"Agente autónomo configurado para o teu negócio.",status:"Em pausa",tasks:"0",color:"violet"});notify(isWorkflow?"Proposta de workflow criada.":"Agente criado em pausa.");close();}}>{isWorkflow?"Gerar proposta":"Criar agente"}</Button></div></div></div>;
}

createRoot(document.getElementById("root")).render(<App/>);
